parameters.jsCode:
// Parse and defensively validate the AI's JSON output before saving.
const raw = $input.first().json.message?.content || $input.first().json.choices?.[0]?.message?.content;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { success: false, error: 'AI response was not valid JSON', raw } }];
}

const score = Number(parsed.match_score);
if (Number.isNaN(score) || score < 0 || score > 100) {
  return [{ json: { success: false, error: 'Invalid match_score from AI', raw: parsed } }];
}

return [{ json: { success: true, result: parsed } }];

